package com.oms.order.service;

import java.util.*;
import static com.oms.order.service.OrderValues.*;

/** Called under the shared order/shipment transaction; registering parcels never consumes stock. */
final class OrderShipmentOutboundRecords {
    private final OrderRepository repository;
    OrderShipmentOutboundRecords(OrderRepository repository){this.repository=repository;}
    void virtual(String company,Map<String,Object> shipment,Map<String,Object> payload,String actor){String json=encode(payload);repository.db().update("INSERT INTO oms_order_shipment_outbound(company_code,shipment_id,shipment_sn,request_id,source_mode,quantity,payload_json,payload_hash,state,created_by,outbound_time,completed_at) VALUES (?,?,?,?,'VIRTUAL',?,?,?,'COMPLETED',?,NOW(),NOW())",company,shipment.get("id"),shipment.get("shipment_sn"),payload.get("request_id"),payload.get("quantity"),json,hash(json),actor);}
    @SuppressWarnings("unchecked") long packageRecord(String company,Map<String,Object> shipment,Long outbound,Map<String,Object> pack,String mode,String request,String actor){
        String code=text(pack,"package_code"),express=text(pack,"express_code"),carrier=text(pack,"carrier_code"),outTime=text(pack,"outbound_time");require(code.matches("[A-Za-z0-9_.-]{1,100}")&&express.matches("[A-Za-z0-9_-]{1,100}")&&(carrier.matches("[A-Za-z0-9_-]{1,64}")||"WMS".equals(mode)&&carrier.isEmpty()),"请填写有效包裹编码、快递及运单号");if(!outTime.isEmpty())time(outTime);require(pack.get("lines") instanceof List&&!((List<?>)pack.get("lines")).isEmpty()&&((List<?>)pack.get("lines")).size()<=500,"包裹明细须为1至500行");List<Map<String,Object>> lines=new ArrayList<>();Set<Long> seen=new HashSet<>();long total=0;
        for(Object raw:(List<?>)pack.get("lines")){require(raw instanceof Map,"包裹明细无效");Map<String,Object> input=(Map<String,Object>)raw;long id=number(input,"id"),quantity=number(input,"quantity");require(id>0&&quantity>0&&quantity<=100000000&&seen.add(id),"包裹行重复或数量无效");List<Map<String,Object>> found=repository.db().query("SELECT id,sku_sn,platform_oid,shipped_quantity FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=? AND id=? FOR UPDATE",ROW,company,shipment.get("id"),id);require(found.size()==1,"包裹行不属于该发货单");Map<String,Object> line=found.get(0);if(input.containsKey("sku_sn"))require(text(line,"sku_sn").equals(text(input,"sku_sn")),"包裹商品与原发货行不一致");lines.add(new LinkedHashMap<>(input));total+=quantity;}
        lines.sort(Comparator.comparingLong(l->number(l,"id")));Map<String,Object> fingerprint=new TreeMap<>();for(String field:Arrays.asList("package_code","express_code","carrier_code","warehouse_carrier_code","outbound_time"))fingerprint.put(field,text(pack,field));List<Map<String,Object>> quantities=new ArrayList<>();for(Map<String,Object> l:lines){Map<String,Object> q=new TreeMap<>();q.put("id",number(l,"id"));q.put("quantity",number(l,"quantity"));quantities.add(q);}fingerprint.put("lines",quantities);String digest=hash(encode(fingerprint));List<Map<String,Object>> prior=repository.db().query("SELECT id,shipment_id,payload_hash,source_mode,request_id FROM oms_order_shipment_package WHERE company_code=? AND (request_id=? OR (shipment_id=? AND package_code=?)) FOR UPDATE",ROW,company,request,shipment.get("id"),code);if(!prior.isEmpty()){require(prior.size()==1&&number(prior.get(0),"shipment_id")==number(shipment,"id")&&digest.equals(text(prior.get(0),"payload_hash"))&&mode.equals(text(prior.get(0),"source_mode")),"该运单或包裹已登记，来源、商品数量或所属发货单不同");return number(prior.get(0),"id");}
        checkWaybill(company,shipment,pack,mode);
        for(Map<String,Object> line:lines){long packed=repository.db().queryForObject("SELECT COALESCE(SUM(quantity),0) FROM oms_order_shipment_package_line WHERE company_code=? AND shipment_line_id=?",Long.class,company,line.get("id"));long shipped=repository.db().queryForObject("SELECT shipped_quantity FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=? AND id=?",Long.class,company,shipment.get("id"),line.get("id"));require(packed+number(line,"quantity")<=shipped,"包裹数量超过已出库且尚未登记运单的数量");}
        repository.db().update("INSERT INTO oms_order_shipment_package(company_code,shipment_id,outbound_id,package_code,carrier_code,carrier_name,warehouse_carrier_code,express_code,source_mode,payload_hash,request_id,quantity,outbound_time,created_by,shared_review_id,waybill_slot) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,COALESCE(?,NOW()),?,?,?)",company,shipment.get("id"),outbound,code,carrier,text(pack,"carrier_name"),text(pack,"warehouse_carrier_code"),express,mode,digest,request,total,outTime.isEmpty()?null:outTime,actor,number(pack,"shared_review_id")>0?number(pack,"shared_review_id"):null,"WMS".equals(mode)?hash(shipment.get("id")+"/"+code):"");long id=repository.db().queryForObject("SELECT id FROM oms_order_shipment_package WHERE company_code=? AND request_id=?",Long.class,company,request);repository.db().update("UPDATE oms_order_shipment_package SET standard_id=?,carrier_resolution_state=?,carrier_resolution_json=?,raw_carrier_name=? WHERE company_code=? AND id=?",number(pack,"standard_id")>0?pack.get("standard_id"):null,text(pack,"carrier_resolution_state").isEmpty()?"RESOLVED":pack.get("carrier_resolution_state"),pack.get("carrier_resolution_json"),text(pack,"raw_carrier_name"),company,id);
        if(number(shipment,"mandated_standard_id")>0&&number(pack,"standard_id")>0&&number(shipment,"mandated_standard_id")!=number(pack,"standard_id")){Map<String,Object> ctx=new LinkedHashMap<>();ctx.put("system_type","CHANNEL");ctx.put("provider","TMALL");ctx.put("purpose","CHANNEL_SHIPPING");ctx.put("shop_id",text(shipment,"channel_id"));ctx.put("standard_id",pack.get("standard_id"));ctx.put("mandated_standard_id",shipment.get("mandated_standard_id"));ctx.put("direction","OUT");new SharedCarrierRouting(repository).issue(company,shipment,code,"PLATFORM_SHIPPING",ctx,com.oms.common.carrier.CarrierResolver.result("MANDATE_MISMATCH","实际快递与平台明确指定不一致，原始物流和有效出库结果已保留"));}
        if(pack.get("carrier_context") instanceof Map&&!"RESOLVED".equals(text(pack,"carrier_resolution_state"))){Map<String,Object> ctx=(Map<String,Object>)pack.get("carrier_context");new SharedCarrierRouting(repository).issue(company,shipment,code,"RESOLVE_ACTUAL",ctx,SharedCarrierRouting.object(pack.get("carrier_resolution_json")));}
        for(Map<String,Object> line:lines)repository.db().update("INSERT INTO oms_order_shipment_package_line(company_code,package_id,shipment_line_id,sku_sn,platform_oid,quantity) SELECT ?,?,id,sku_sn,platform_oid,? FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=? AND id=?",company,id,line.get("quantity"),company,shipment.get("id"),line.get("id"));return id;
    }
    void checkWaybill(String company,Map<String,Object> shipment,Map<String,Object> pack,String mode){
        String carrier=text(pack,"carrier_code"),express=text(pack,"express_code");if("WMS".equals(mode)&&carrier.isEmpty())return;
        repository.db().update("INSERT IGNORE INTO oms_order_waybill_lock(company_code,carrier_code,express_code) VALUES (?,?,?)",company,carrier,express);
        repository.db().query("SELECT express_code FROM oms_order_waybill_lock WHERE company_code=? AND carrier_code=? AND express_code=? FOR UPDATE",ROW,company,carrier,express);
        List<Map<String,Object>> peers=repository.db().query("SELECT p.shipment_id,p.package_code,p.source_mode,s.order_id FROM oms_order_shipment_package p JOIN oms_order_shipment s ON s.company_code=p.company_code AND s.id=p.shipment_id WHERE p.company_code=? AND p.carrier_code=? AND p.express_code=?",ROW,company,carrier,express);
        for(Map<String,Object> peer:peers){if(number(peer,"shipment_id")==number(shipment,"id")&&text(peer,"package_code").equals(text(pack,"package_code")))continue;
            require("WMS".equals(mode)&&(number(peer,"shipment_id")==number(shipment,"id")||number(pack,"shared_review_id")>0)&&number(shipment,"order_id")>0&&number(shipment,"order_id")==number(peer,"order_id")&&"WMS".equals(text(peer,"source_mode")),"该运单已关联其他包裹，需人工核对共用运单后处理");
        }
    }
    Map<String,Object> warehouseCarrier(String company,Map<String,Object> shipment,String logistics){return new SharedCarrierRouting(repository).actual(company,shipment,logistics);}
    private Map<String,Object> carrier(Map<String,Object> shipment){Map<String,Object> c=new LinkedHashMap<>();for(String field:Arrays.asList("carrier_code","carrier_name","warehouse_carrier_code"))c.put(field,text(shipment,field));return c;}
    void detail(String company,Map<String,Object> shipment){long id=number(shipment,"id");List<Map<String,Object>> records=repository.db().query("SELECT id,source_mode,quantity,state,message_id,final_confirmation,outbound_time,last_error,attempts,create_time,completed_at,created_by,payload_json FROM oms_order_shipment_outbound WHERE company_code=? AND shipment_id=? ORDER BY id DESC",ROW,company,id);for(Map<String,Object> record:records){try{record.put("lines",JSON.readTree(text(record,"payload_json")).path("lines"));}catch(Exception e){record.put("snapshot_error","出库来源快照无法解析");}record.remove("payload_json");}shipment.put("outbound_records",records);List<Map<String,Object>> packs=repository.db().query("SELECT id,package_code,express_code,carrier_code,carrier_name,warehouse_carrier_code,source_mode,quantity,outbound_time,create_time,created_by,shared_review_id,standard_id,carrier_resolution_state,raw_carrier_name FROM oms_order_shipment_package WHERE company_code=? AND shipment_id=? ORDER BY id",ROW,company,id);Map<Long,List<Map<String,Object>>> byPackage=new HashMap<>();for(Map<String,Object> line:repository.db().query("SELECT p.package_id,p.shipment_line_id,p.sku_sn,p.platform_oid,p.quantity,l.goods_name,l.store_code,l.batch_id FROM oms_order_shipment_package_line p JOIN oms_order_shipment_package h ON h.company_code=p.company_code AND h.id=p.package_id JOIN oms_order_shipment_line l ON l.company_code=p.company_code AND l.id=p.shipment_line_id WHERE h.company_code=? AND h.shipment_id=? ORDER BY p.id",ROW,company,id))byPackage.computeIfAbsent(number(line,"package_id"),k->new ArrayList<>()).add(line);for(Map<String,Object> pack:packs)pack.put("lines",byPackage.getOrDefault(number(pack,"id"),Collections.emptyList()));shipment.put("packages",packs);}
}
